// NewMissionServiceHandler builds an HTTP handler from the service implementation. It returns the
// path on which to mount the handler and the handler itself.
//
// By default, handlers support the Connect, gRPC, and gRPC-Web protocols with the binary Protobuf
// and JSON codecs. They also support gzip compression.
func NewMissionServiceHandler(svc MissionServiceHandler, opts ...connect.HandlerOption) (string, http.Handler) {
	missionServiceMethods := v1.File_registry_v1_registry_proto.Services().ByName("MissionService").Methods()
	missionServiceUploadMissionHandler := connect.NewUnaryHandler(
		MissionServiceUploadMissionProcedure,
		svc.UploadMission,
		connect.WithSchema(missionServiceMethods.ByName("UploadMission")),
		connect.WithHandlerOptions(opts...),
	)
	missionServiceGetMissionHandler := connect.NewUnaryHandler(
		MissionServiceGetMissionProcedure,
		svc.GetMission,
		connect.WithSchema(missionServiceMethods.ByName("GetMission")),
		connect.WithHandlerOptions(opts...),
	)
	missionServiceListMissionsHandler := connect.NewUnaryHandler(
		MissionServiceListMissionsProcedure,
		svc.ListMissions,
		connect.WithSchema(missionServiceMethods.ByName("ListMissions")),
		connect.WithHandlerOptions(opts...),
	)
	missionServiceDeleteMissionHandler := connect.NewUnaryHandler(
		MissionServiceDeleteMissionProcedure,
		svc.DeleteMission,
		connect.WithSchema(missionServiceMethods.ByName("DeleteMission")),
		connect.WithHandlerOptions(opts...),
	)
	missionServiceSetMissionMetadataHandler := connect.NewUnaryHandler(
		MissionServiceSetMissionMetadataProcedure,
		svc.SetMissionMetadata,
		connect.WithSchema(missionServiceMethods.ByName("SetMissionMetadata")),
		connect.WithHandlerOptions(opts...),
	)
	return "/registry.v1.MissionService/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case MissionServiceUploadMissionProcedure:
			missionServiceUploadMissionHandler.ServeHTTP(w, r)
		case MissionServiceGetMissionProcedure:
			missionServiceGetMissionHandler.ServeHTTP(w, r)
		case MissionServiceListMissionsProcedure:
			missionServiceListMissionsHandler.ServeHTTP(w, r)
		case MissionServiceDeleteMissionProcedure:
			missionServiceDeleteMissionHandler.ServeHTTP(w, r)
		case MissionServiceSetMissionMetadataProcedure:
			missionServiceSetMissionMetadataHandler.ServeHTTP(w, r)
		default:
			http.NotFound(w, r)
		}
	})
}

